#!/usr/bin/env bash
# Fix script for INC-0007: OOMKilled in bank-sim/c07-oomkilled
# Root cause (confirmed, 90%): The container uses more memory than its limit of 64Mi, so the kernel's OOM killer ends it (exit code 137) and Kubernetes restarts it.
# Approval: Approved. Generated by the read-only SRE agent, which did NOT run it.
# Review every step. Usage: bash this-file [--check | --rollback]
set -euo pipefail
CLUSTER=bank-sim
MODE="${1:-fix}"
TTY="${FIX_TTY:-/dev/tty}"  # answers come from the terminal, even if this file is piped

ctx=$(kubectl config current-context 2>/dev/null || true)
if [[ "$ctx" != *"$CLUSTER"* ]]; then
  echo "Refusing: kubectl context \"$ctx\" is not cluster $CLUSTER (kubectl config use-context ...)" >&2; exit 2
fi
run()    { printf "\n\033[1m$ %s\033[0m\n" "$1"; bash -o pipefail -c "$1"; }
check()  { printf "\n\033[1m$ %s\033[0m\n" "$1"; bash -o pipefail -c "$1" || echo "(check failed; continuing)"; }
change() { printf "\n\033[1;33mCHANGE:\033[0m %s\n" "$1"; read -rp "Run this change? [y/N] " a <"$TTY"; [ "$a" = y ] || { echo "Stopped before the change."; exit 1; }; bash -o pipefail -c "$1" <"$TTY"; }
manual() { printf "\n\033[1;36mMANUAL STEP:\033[0m %s\n" "$1"; read -rp "Press Enter when done (Ctrl+C to stop) " _ <"$TTY"; }

echo "== INC-0007: OOMKilled on $CLUSTER (namespace c07-oomkilled) =="

# ---------------------------------------------------------------- 1. read-only checks
# Container states, restart counts, resource settings and the pod's events (at the bottom).
check 'kubectl -n c07-oomkilled describe pod cache-warmer-6c9d7b8f5d-q2x7z'
# What the app did just before it was killed.
check 'kubectl -n c07-oomkilled logs cache-warmer-6c9d7b8f5d-q2x7z -c app --previous --tail=50'
# Memory usage now; compare with the limit.
check 'kubectl -n c07-oomkilled top pod cache-warmer-6c9d7b8f5d-q2x7z --containers'
# Did a recent release change memory behaviour?
check 'kubectl -n c07-oomkilled rollout history deployment/cache-warmer'
[ "$MODE" = "--check" ] && { echo; echo "Checks done (no changes)."; exit 0; }

# ---------------------------------------------------------------- rollback (only with --rollback)
if [ "$MODE" = "--rollback" ]; then
  # Returns the Deployment to its previous revision if the change makes things worse (with GitOps: revert the commit instead).
  change 'kubectl -n c07-oomkilled rollout undo deployment/cache-warmer'
  echo; echo "Rollback done."; exit 0
fi

# ---------------------------------------------------------------- 2. the fix (asks before each change)
# Limit 128Mi = max(2 x the current limit, 1.5 x measured usage); request 96Mi keeps the scheduler honest. A stop-gap if usage keeps growing (leak): then fix or roll back. This workload is deployed by Argo CD (GitOps). Make the change in Git and let Argo CD sync it; a kubectl change is drift and is overwritten or flagged at the next sync.
change 'kubectl -n c07-oomkilled set resources deployment/cache-warmer -c app --requests=memory=96Mi --limits=memory=128Mi'

# ---------------------------------------------------------------- 3. verify
# Waits until every replica of the new version is available.
check 'kubectl -n c07-oomkilled rollout status deployment/cache-warmer --timeout=180s'
# Pods should be Running and READY with no new restarts.
check 'kubectl -n c07-oomkilled get pods -o wide -l app.kubernetes.io/name=cache-warmer'
# Restart counts stay the same for 15+ minutes.
check 'kubectl -n c07-oomkilled get pod -l app.kubernetes.io/name=cache-warmer -o custom-columns=POD:.metadata.name,RESTARTS:.status.containerStatuses[0].restartCount'

echo; echo "Done. If it got worse: bash $0 --rollback. Then record the actions in the RCA (INC-0007)."
